fn less<T,F:FnMut(&T,&T)->bool>(a:&T,b:&T,f:&mut F)->bool{f(a,b)}fn more<T,F:FnMut(&T,&T)->bool>(a:&T,b:&T,f:&mut F)->bool{f(b,a)}const fn pick<T,F:FnMut(&T,&T)->bool,const FLIP:bool>()->fn(&T,&T,&mut F)->bool{if FLIP{more::<T,F>}else{less::<T,F>}}fn order<T,F:FnMut(&T,&T)->bool,const FLIP:bool>(a:&T,b:&T,f:&mut F)->bool{(const{pick::<T,F,FLIP>()})(a,b,f)}pub fn run()->bool{let mut lt=|a:&u8,b:&u8|*a<*b;order::<u8,_,false>(&1,&2,&mut lt)&&!order::<u8,_,true>(&1,&2,&mut lt)}
